update events set end_date='2026-11-29', time_text='Sat 28 and Sun 29 November, 6pm–8.30pm (Parklands from 4pm)', price_text='Free. Stage area sold out; big screen in HOTA Parklands', address='HOTA Outdoor Stage and Parklands, 135 Bundall Road, Surfers Paradise', lead='The Gold Coast''s biggest carols night celebrates its 15th year at HOTA over two nights, with Samantha Jade, Havana Brown, the Royal Navy Band and a fireworks finale.', about='The City of Gold Coast''s Mayor''s Christmas Carols return to HOTA, Home of the Arts, for their 15th year, on Saturday 28 and Sunday 29 November from 6pm to 8.30pm.

ARIA Award-winning singer Samantha Jade headlines, joined by DJ Havana Brown, the Royal Navy Band Queensland, Warner Bros. Movie World''s Looney Tunes Christmas Show and a visit from Santa. 7NEWS presenters Amanda Abate and Chris Parsons host, Auslan interpreters are on stage, and each night ends with fireworks.

The event is free, but the ticketed Outdoor Stage area is fully allocated. Everyone else can bring a picnic blanket to the HOTA Parklands for a family-friendly big-screen broadcast, with food trucks and free Ferris wheel rides from 4pm.', story='[{"type": "text", "text": "For 15 years, the Mayor''s Christmas Carols have been the Gold Coast''s big night of Christmas song. This year they run over two evenings, Saturday 28 and Sunday 29 November, at HOTA, Home of the Arts, on Bundall Road."}, {"type": "image", "url": "/images/library/unsplash-aaron-burden-silent-night.jpg", "alt": "Open song book on the Silent Night page with warm lights behind", "layout": "right", "caption": "Stand-in photo: Aaron Burden. Mayor''s Christmas Carols photos coming soon"}, {"type": "text", "text": "ARIA Award-winning singer Samantha Jade headlines the show, with DJ Havana Brown, the Royal Navy Band Queensland and Warner Bros. Movie World''s Looney Tunes Christmas Show. Santa makes an appearance, 7NEWS presenters Amanda Abate and Chris Parsons host, and Auslan interpreters sign the whole program. Each night finishes with fireworks.", "heading": "The line-up"}, {"type": "text", "text": "Tickets for the Outdoor Stage area have all been allocated, but you can still be part of it. Spread a picnic blanket on the HOTA Parklands, where the show plays on a big screen. Food trucks and free Ferris wheel rides open from 4pm, so come early and make an evening of it.", "heading": "No ticket? Head to the Parklands"}, {"type": "text", "text": "Parking around HOTA is limited, so public transport, walking or cycling is the easiest way in. If you drive, HOTA''s meters offer four hours of free parking when you enter your rego.", "heading": "Getting there"}]'::jsonb, highlights='[{"title": "15th year", "detail": "Two nights at HOTA"}, {"title": "Samantha Jade", "detail": "Plus Havana Brown and the Royal Navy Band"}, {"title": "Fireworks", "detail": "To finish each night"}]'::jsonb, good_to_know='["Free; the Outdoor Stage area is fully allocated", "Big-screen broadcast in the HOTA Parklands", "Food trucks and free Ferris wheel rides from 4pm", "Auslan interpreters on stage", "Bring a picnic blanket", "Parking is limited: four hours free at HOTA meters with your rego"]'::jsonb, venue_about='HOTA, Home of the Arts, is the Gold Coast''s arts centre on Bundall Road, with an outdoor stage set in parklands beside the Nerang River.', maps_url='https://www.google.com/maps/search/?api=1&query=HOTA%2C%20Home%20of%20the%20Arts%2C%20135%20Bundall%20Road%2C%20Surfers%20Paradise%20QLD%204217', updated_at=now() where slug='gold-coast-mayors-christmas-carols';
update events set time_text='5pm–8pm, fireworks at 8pm', venue='Runaway Bay Soccer Fields', address='Runaway Bay Soccer Fields, Lae Drive, Runaway Bay', lead='A free carols night on the northern Gold Coast with a live band, local singers and school choirs, free face painting, and Santa joining the countdown to fireworks at 8pm.', about='Runaway Bay Carols by Candlelight fills the Runaway Bay Soccer Fields on Lae Drive on Saturday 28 November, from 5pm to 8pm.

John Kerr from 94.1FM and Danielle Goullet host, with performances from Brett Mills, Leah Lever, Jack Watson, Sharon Rowntree, Craig Martin, local school choirs and a live seven-piece band. There''s free face painting, food vendors and sweet treats, glow products to buy, and visits from Christmas characters.

Santa joins the countdown to a fireworks finale at 8pm. Entry is free; bring a picnic rug. The event is run by the City of Gold Coast''s Division 4 office.', story='[{"type": "text", "text": "On the last Saturday in November, the northern Gold Coast gathers on the Runaway Bay Soccer Fields for an evening of candles and carols. The free event runs from 5pm to 8pm, so it''s easy to bring the whole family."}, {"type": "image", "url": "/images/library/unsplash-aaron-burden-silent-night.jpg", "alt": "Open song book on the Silent Night page with warm lights behind", "layout": "right", "caption": "Stand-in photo: Aaron Burden. Runaway Bay Carols by Candlelight photos coming soon"}, {"type": "text", "text": "Hosts John Kerr from 94.1FM and Danielle Goullet introduce a line-up of local voices: Brett Mills, Leah Lever, Jack Watson, Sharon Rowntree and Craig Martin, with local school choirs and a live seven-piece band leading the singalong.", "heading": "Local singers and school choirs"}, {"type": "text", "text": "Children can have their faces painted for free and meet Christmas characters, and food vendors have dinner and sweet treats covered. Glow products are on sale for when the candles come out. At 8pm, Santa joins the countdown to the fireworks finale.", "heading": "Face painting, glow sticks and fireworks"}]'::jsonb, highlights='[{"title": "Free", "detail": "5pm to 8pm"}, {"title": "Fireworks", "detail": "8pm, with Santa''s countdown"}, {"title": "7-piece band", "detail": "Plus local school choirs"}]'::jsonb, good_to_know='["Free entry", "Fireworks at 8pm", "Free face painting", "Food vendors on site; glow products for sale", "Bring a picnic rug", "Parking may be limited; public transport encouraged", "Organiser: City of Gold Coast Division 4, 07 5581 1680"]'::jsonb, maps_url='https://www.google.com/maps/search/?api=1&query=Runaway%20Bay%20Soccer%20Fields%2C%20Lae%20Drive%2C%20Runaway%20Bay%20QLD%204216', updated_at=now() where slug='runaway-bay-carols-by-candlelight';
update events set time_text='4pm–8pm. Stage entertainment from 6pm', venue='Ed Hardy Park', address='Ed Hardy Park, The Esplanade, Miami', lead='Carols by the beach at Ed Hardy Park, Miami, with children''s activities, food trucks and markets from 4pm, and Christmas stage entertainment from 6pm.', about='North Burleigh Carols by the Sea brings the community together at Ed Hardy Park on The Esplanade at Miami on Thursday 3 December, from 4pm to 8pm.

Children''s activities, food trucks and market stalls open from 4pm, and the Christmas stage program starts at 6pm with carols, community groups and live music.

It''s free, presented by Division 12 Councillor Nick Marshall and run by The Events Agency. Parking may be limited, so walking, cycling or public transport is the easiest way to get there.', story='[{"type": "text", "text": "A midweek carols evening with an ocean breeze: North Burleigh Carols by the Sea sets up at Ed Hardy Park on The Esplanade at Miami on Thursday 3 December."}, {"type": "image", "url": "/images/library/unsplash-aaron-burden-silent-night.jpg", "alt": "Open song book on the Silent Night page with warm lights behind", "layout": "right", "caption": "Stand-in photo: Aaron Burden. North Burleigh Carols by the Sea photos coming soon"}, {"type": "text", "text": "From 4pm, children''s activities, food trucks and market stalls fill the park, so you can grab dinner and browse while the kids play. At 6pm the Christmas stage comes alive with carols, community groups and live music, running until 8pm.", "heading": "Markets from 4pm, carols from 6pm"}, {"type": "text", "text": "The event is free, presented by Division 12 Councillor Nick Marshall and organised by The Events Agency. Bring a picnic rug and plan to walk, cycle or catch public transport, as beachside parking fills quickly.", "heading": "Before you go"}]'::jsonb, highlights='[{"title": "Free", "detail": "4pm to 8pm"}, {"title": "Beachside", "detail": "Ed Hardy Park, Miami"}, {"title": "Markets", "detail": "Food trucks and stalls from 4pm"}]'::jsonb, good_to_know='["Free", "Children''s activities, food trucks and markets from 4pm", "Stage entertainment from 6pm", "Bring a picnic rug", "Parking may be limited", "Organiser: The Events Agency, 1300 855 270"]'::jsonb, maps_url='https://www.google.com/maps/search/?api=1&query=Ed%20Hardy%20Park%2C%20The%20Esplanade%2C%20Miami%20QLD%204220', updated_at=now() where slug='north-burleigh-carols-by-the-sea';
update events set time_text='4pm–8pm', price_text='Free', venue='Toolona Street', address='Toolona Street, Tugun', lead='Tugun''s 13th annual Christmas street celebration, with market stalls, children''s entertainment, local cafés and a visit from Santa on Toolona Street.', about='Tugun Lights Up returns for its 13th year on Saturday 5 December, from 4pm to 8pm on Toolona Street.

Christmas market stalls and local businesses line the street, children''s entertainment runs throughout, and Santa makes a special appearance. Stay for dinner at one of Tugun''s local cafés and restaurants.

It''s free, presented by Division 14 Councillor Gail O''Neill with Community Bank Tugun, and run by The Events Agency.', story='[{"type": "text", "text": "For one evening each December, Toolona Street becomes the heart of Christmas on the southern Gold Coast. Tugun Lights Up is back for its 13th year on Saturday 5 December, from 4pm to 8pm."}, {"type": "image", "url": "/images/library/unsplash-josh-hild-market.jpg", "alt": "Festive street market under lit trees", "layout": "right", "caption": "Stand-in photo: Josh Hild. Tugun Lights Up photos coming soon"}, {"type": "text", "text": "Christmas market stalls and local businesses set up along the street, and children''s entertainment runs all evening. Santa drops in for a special appearance, so have the camera ready.", "heading": "Stalls, entertainment and Santa"}, {"type": "text", "text": "Make a night of it with dinner at one of Tugun''s local cafés or restaurants. The event is free and presented by Division 14 Councillor Gail O''Neill in partnership with Community Bank Tugun.", "heading": "Stay for dinner"}]'::jsonb, highlights='[{"title": "13th year", "detail": "A Tugun tradition"}, {"title": "Free", "detail": "4pm to 8pm"}, {"title": "Santa", "detail": "Special appearance"}]'::jsonb, good_to_know='["Free", "Saturday 5 December, 4pm to 8pm", "Christmas market stalls and local businesses", "Children''s entertainment all evening", "Parking may be limited; public transport encouraged", "Organiser: The Events Agency, 1300 855 270"]'::jsonb, maps_url='https://www.google.com/maps/search/?api=1&query=Toolona%20Street%2C%20Tugun%20QLD%204224', updated_at=now() where slug='tugun-lights-up';
update events set lead='A twilight Christmas market at the Mudgeeraba Showgrounds in the Gold Coast hinterland, with stalls for gifts and food.', story='[{"type": "text", "text": "The Mudgeeraba Showgrounds in Worongary host a twilight Christmas market, a relaxed hinterland evening of browsing stalls for gifts and grabbing something to eat as the sun goes down."}, {"type": "image", "url": "/images/library/unsplash-josh-hild-market.jpg", "alt": "Festive street market under lit trees", "layout": "right", "caption": "Stand-in photo: Josh Hild. Mudgeeraba Twilight Christmas Markets photos coming soon"}, {"type": "text", "text": "Past Christmas markets here have featured local market stalls, food trucks, live music and a visit from Santa, with families bringing picnic blankets. This year''s times and line-up hadn''t been published when we checked, so look at the official listing before you go.", "heading": "Before you go"}]'::jsonb, highlights='[{"title": "Twilight market", "detail": "Mudgeeraba Showgrounds"}, {"title": "Local stalls", "detail": "Gifts and food"}, {"title": "Hinterland", "detail": "Worongary, Gold Coast"}]'::jsonb, good_to_know='["Check the official listing for times and entry", "Bring a picnic blanket", "Showgrounds address: 115 Mudgeeraba Road, Worongary"]'::jsonb, address='Mudgeeraba Showgrounds, 115 Mudgeeraba Road, Worongary', maps_url='https://www.google.com/maps/search/?api=1&query=Mudgeeraba%20Showgrounds%2C%20115%20Mudgeeraba%20Road%2C%20Worongary%20QLD%204213', updated_at=now() where slug='mudgeeraba-twilight-christmas-markets';
update events set address='Raby Bay Harbour Park, Shore Street West, Cleveland', lead='Two free evenings at Raby Bay Harbour Park: free photos with Coastal Santa, carols, the lighting of the Redlands Coast Christmas tree and a movie under the stars.', about='Redlands Coast''s Christmas tree is switched on at Raby Bay Harbour Park in Cleveland on Friday 27 and Saturday 28 November, from 4.30pm to 8.30pm each night.

The park opens at 4.30pm with activities, food trucks and roving performers, and free photos with Coastal Santa run until 6.15pm. The stage program starts at 4.45pm, the official tree lighting is at 6.30pm, community carols follow at 6.45pm, and a movie starts at 7.15pm: The Santa Clause on Friday and Home Alone 2: Lost in New York on Saturday.

It''s free with no tickets needed. Bring chairs, rugs and your own non-alcoholic food and drink; glass and alcohol aren''t allowed. Cleveland train station is directly opposite.', story='[{"type": "text", "text": "Raby Bay Harbour Park becomes a Christmas gathering place on the last weekend of November, as Redlands Coast lights its Christmas tree over two free evenings, Friday 27 and Saturday 28 November."}, {"type": "image", "url": "/images/library/unsplash-abishanth-ahilan-fireworks.jpg", "alt": "Golden fireworks against a dark night sky", "layout": "right", "caption": "Stand-in photo: Abishanth Ahilan. Redlands Coast Lighting of the Christmas Tree photos coming soon"}, {"type": "text", "text": "The park opens at 4.30pm with activities, food trucks and roving performers. Free photos with Coastal Santa run from 4.30pm to 6.15pm, and you can download your photo free after the event, so join the queue before 6pm. The stage program starts at 4.45pm.", "heading": "Free photos with Coastal Santa"}, {"type": "text", "text": "At 6.30pm the official proceedings begin and the Christmas tree is lit, followed by community carols at 6.45pm, with lyrics on the screens. Then settle in for a movie at 7.15pm: The Santa Clause (G) on Friday, or Home Alone 2: Lost in New York (PG) on Saturday.", "heading": "Tree lighting, carols and a movie"}, {"type": "text", "text": "Bring chairs, blankets, an esky and your own non-alcoholic food and drink. Glass, alcohol, tents, tables and large umbrellas aren''t allowed. There''s an accessible, shaded viewing area, accessible toilets and accessible pathways. Parking in Cleveland is limited, but the train station is directly opposite the park.", "heading": "Know before you go"}]'::jsonb, highlights='[{"title": "Free Santa photos", "detail": "4.30pm to 6.15pm"}, {"title": "Tree lighting", "detail": "6.30pm both nights"}, {"title": "Movie night", "detail": "Starts 7.15pm"}]'::jsonb, good_to_know='["Free, no tickets needed", "Join the Santa queue before 6pm", "Bring chairs, rugs and non-alcoholic food and drink", "No glass or alcohol", "Accessible shaded viewing area and accessible toilets", "Cleveland train station is opposite the park"]'::jsonb, venue_about='Raby Bay Harbour Park sits on the waterfront in Cleveland, opposite Cleveland train station.', maps_url='https://www.google.com/maps/search/?api=1&query=Raby%20Bay%20Harbour%20Park%2C%20Shore%20Street%20West%2C%20Cleveland%20QLD%204163', updated_at=now() where slug='redlands-coast-lighting-of-the-christmas-tree';
update events set price_text='Free', address='Kinsellas Sports Complex, 1 Innovation Place, North Lakes', lead='City of Moreton Bay''s free carols night at Kinsellas Sports Complex, with a stage program, free kids'' activities, a visit from Santa and a fireworks finale.', about='The City of Moreton Bay presents North Lakes Christmas Carols at Kinsellas Sports Complex on Saturday 5 December, from 4pm.

Expect a stage program of Christmas entertainment, free activities for children and a visit from Santa, with the night closing in a fireworks finale.

Entry is free and there''s a car park on site. Bring a picnic rug and settle in for the evening.', story='[{"type": "text", "text": "North Lakes gathers at Kinsellas Sports Complex on the first Saturday in December for the City of Moreton Bay''s Christmas carols, starting from 4pm."}, {"type": "image", "url": "/images/library/unsplash-aaron-burden-silent-night.jpg", "alt": "Open song book on the Silent Night page with warm lights behind", "layout": "right", "caption": "Stand-in photo: Aaron Burden. North Lakes Christmas Carols photos coming soon"}, {"type": "text", "text": "A stage program of Christmas entertainment runs through the evening, with free activities to keep children busy and a visit from Santa. As night falls, the carols build to a fireworks finale.", "heading": "Carols, Santa and fireworks"}, {"type": "text", "text": "Entry is free and there''s a car park on site. Bring a picnic rug and get there early to choose your spot on the grass.", "heading": "Before you go"}]'::jsonb, highlights='[{"title": "Free", "detail": "From 4pm"}, {"title": "Fireworks", "detail": "Finale to close the night"}, {"title": "Free kids'' activities", "detail": "And a visit from Santa"}]'::jsonb, good_to_know='["Free entry", "Saturday 5 December from 4pm", "Car park on site", "Bring a picnic rug", "Presented by City of Moreton Bay, 07 3453 1400"]'::jsonb, maps_url='https://www.google.com/maps/search/?api=1&query=Kinsellas%20Sports%20Complex%2C%201%20Innovation%20Place%2C%20North%20Lakes%20QLD%204509', updated_at=now() where slug='north-lakes-christmas-carols';
update events set price_text='Free', address='Griffith University Logan Campus, 68 University Drive, Meadowbrook', official_url='https://www.logan.qld.gov.au/whats-on/events/christmas-carols', lead='Logan''s big free carols night at Griffith University''s Meadowbrook campus, with local choirs, free rides and activities, food and market stalls, and fireworks to finish.', about='The City of Logan Christmas Carols are on Saturday 5 December from 3pm to 8pm at Griffith University''s Logan campus in Meadowbrook.

The stage program mixes classic Christmas carols with contemporary performances from local choirs and performers. There''s a huge range of free activities and rides, food and market stalls, and the night ends with fireworks.

Entry is free. Bring a picnic rug and low chairs for the lawn; tents, shelters and in-ground umbrellas aren''t allowed.', story='[{"type": "text", "text": "Logan''s community comes together on the lawns of Griffith University''s Logan campus for the City of Logan Christmas Carols, on Saturday 5 December from 3pm to 8pm."}, {"type": "image", "url": "/images/library/unsplash-aaron-burden-silent-night.jpg", "alt": "Open song book on the Silent Night page with warm lights behind", "layout": "right", "caption": "Stand-in photo: Aaron Burden. City of Logan Christmas Carols photos coming soon"}, {"type": "text", "text": "Local choirs and performers take the stage with classic carols and contemporary favourites, and Santa and his helpers join in the fun.", "heading": "Carols and local choirs"}, {"type": "text", "text": "Children can enjoy a huge range of free activities and rides, and food and market stalls cover dinner. As night falls, the evening finishes with fireworks.", "heading": "Free rides and fireworks"}, {"type": "text", "text": "Bring a picnic rug and low chairs to claim a spot on the lawn. Tents, shelters and in-ground umbrellas aren''t permitted. Follow the City of Logan Christmas Carols Facebook event for updates on the day.", "heading": "Before you go"}]'::jsonb, highlights='[{"title": "Free", "detail": "3pm to 8pm"}, {"title": "Free rides", "detail": "And activities for kids"}, {"title": "Fireworks", "detail": "To end the night"}]'::jsonb, good_to_know='["Free entry", "Bring a picnic rug and low chairs", "No tents, shelters or in-ground umbrellas", "Food and market stalls on site", "Updates on the City of Logan Christmas Carols Facebook event", "Contact: City of Logan, 07 3412 3412"]'::jsonb, maps_url='https://www.google.com/maps/search/?api=1&query=Griffith%20University%20Logan%20Campus%2C%2068%20University%20Drive%2C%20Meadowbrook%20QLD%204131', updated_at=now() where slug='city-of-logan-christmas-carols';
update events set address='Carseldine Markets, 133 Dorville Road, Carseldine', lead='Carseldine Markets'' Christmas twilight edition, with artisan gift stalls, festive food, a pop-up bar, live music, a kids'' disco and Santa.', story='[{"type": "text", "text": "Carseldine Markets on Dorville Road goes after dark for its Christmas twilight market, from 4pm to 10pm. It''s one of Brisbane''s bigger twilight markets, and a good place to tick off Christmas gifts in one go."}, {"type": "image", "url": "/images/library/unsplash-josh-hild-market.jpg", "alt": "Festive street market under lit trees", "layout": "right", "caption": "Stand-in photo: Josh Hild. Carseldine Christmas Twilight Market photos coming soon"}, {"type": "text", "text": "Last year''s Christmas twilight market had more than 200 artisan gift stalls, festive food, a pop-up wine bar, live music and a kids'' disco, with Santa and his crew dropping by. Check the market''s Facebook page for this year''s line-up.", "heading": "Gifts, food and Santa"}]'::jsonb, highlights='[{"title": "Free entry", "detail": "4pm to 10pm"}, {"title": "200+ stalls", "detail": "At last year''s market"}, {"title": "Santa", "detail": "Snaps with Santa"}]'::jsonb, good_to_know='["Free entry", "Car park on site", "Pet friendly; check with the market first", "Pop-up bar and festive food", "Contact Carseldine Markets: 0490 493 760"]'::jsonb, maps_url='https://www.google.com/maps/search/?api=1&query=Carseldine%20Markets%2C%20133%20Dorville%20Road%2C%20Carseldine%20QLD%204034', updated_at=now() where slug='carseldine-christmas-twilight-market';
update events set address='Station Street, Nundah', lead='A Christmas twilight market along Station Street in Nundah, with artisan stalls, gourmet food, a pop-up bar, live music and Santa.', story='[{"type": "text", "text": "Station Street in Nundah fills with stalls for the Christmas twilight markets, from 4pm to 10pm. Wander the street, browse for gifts and stay for dinner and music as the evening cools down."}, {"type": "image", "url": "/images/library/unsplash-josh-hild-market.jpg", "alt": "Festive street market under lit trees", "layout": "right", "caption": "Stand-in photo: Josh Hild. Nundah Christmas Twilight Markets photos coming soon"}, {"type": "text", "text": "Last year''s market had more than 100 artisan stalls, gourmet food vendors, a pop-up bar and live music, plus festive fun for children and photo spots. Kids can meet Santa and have their photo taken.", "heading": "Stalls, music and Santa"}]'::jsonb, highlights='[{"title": "Free entry", "detail": "4pm to 10pm"}, {"title": "100+ stalls", "detail": "At last year''s market"}, {"title": "Meet Santa", "detail": "Photos for the kids"}]'::jsonb, good_to_know='["Free entry", "Meet Santa and take photos", "Pop-up bar and gourmet food", "Car parking available nearby", "Pet friendly; check with the organisers first"]'::jsonb, maps_url='https://www.google.com/maps/search/?api=1&query=Station%20Street%2C%20Nundah%20QLD%204012', updated_at=now() where slug='nundah-christmas-twilight-markets';
